const esc = s => String(s == null ? "" : s).replace(/[&<>"']/g, c => ({"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"}[c]));
const PIC = c => `https://img.heyvoyo.com/clips/${c}.webp`;
// 读完再往下走；机器声没反应（有的手机静音、没装英文声音）也不会卡住：按句子长短估个时间兜底
const say = (t, done, rate) => { let fired = false; const go = () => { if (!fired){ fired = true; done && done(); } };
  if (done) setTimeout(go, 1500 + String(t).length * 85 / (rate || .92));
  try { speechSynthesis.cancel(); const u = new SpeechSynthesisUtterance(t); u.lang = "en-GB"; u.rate = rate || .92; u.onend = u.onerror = go; speechSynthesis.speak(u); } catch(e){ go(); } };
const SR = () => window.SpeechRecognition || window.webkitSpeechRecognition;
// 🔔 声音鼓励（2026-11-07 用户：要有一个声音鼓励）：答对一下「叮」，盖章「叮咚」+ 夸一句（不用音频文件，手机上现做）
let AC = null; const tone = (f, t0, d, v) => { try { AC = AC || new (window.AudioContext || window.webkitAudioContext)(); const o = AC.createOscillator(), g = AC.createGain(), t = AC.currentTime + t0;
  o.type = "sine"; o.frequency.value = f; g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(v, t + .02); g.gain.exponentialRampToValueAtTime(.001, t + d); o.connect(g); g.connect(AC.destination); o.start(t); o.stop(t + d + .05); } catch(e){} };
const ding = () => tone(1318, 0, .25, .12);
