const IDB = () => new Promise(res => { try { const r = indexedDB.open("hv.ty", 1); r.onupgradeneeded = () => r.result.createObjectStore("v"); r.onsuccess = () => res(r.result); r.onerror = () => res(null); } catch(e){ res(null); } });
